mapper.select:
SELECT m.id, m.topic, m.direction, m.payload, m.qos, m.device_id,
       m.sent_at, m.received_at,
       d.device_name AS device_name
FROM message m
LEFT JOIN device d ON m.device_id = d.id AND d.deleted = 0
WHERE 1=1

    AND m.device_id = #{dto.deviceId}


    AND m.topic LIKE CONCAT('%', #{dto.topic}, '%')


    AND m.direction = #{dto.direction}


    AND m.sent_at >= #{dto.startTime}


    AND m.sent_at <= #{dto.endTime}


    AND (m.device_id IS NULL OR d.owner_id = #{userId})

ORDER BY m.sent_at DESC

SELECT m.id, m.device_id, m.topic, m.payload, m.sent_at AS timestamp, m.received_at AS created_at, d.device_name AS device_name FROM message m LEFT JOIN device d ON m.device_id = d.id AND d.deleted = 0 WHERE m.direction = 'SUBSCRIBE' AND m.topic LIKE '%/data'
AND m.device_id = #{dto.deviceId}
AND m.topic LIKE CONCAT('%', #{dto.topic}, '%')
AND m.sent_at >= #{dto.startTime}
AND m.sent_at <= #{dto.endTime}
AND d.owner_id = #{userId}
ORDER BY m.sent_at DESC
